        updatePopupSurfaceSelect();
        setInterval(updatePopupSurfaceSelect, 1000);

        // Keep in sync with the main window.
        setInterval(syncFromOpener, 500);
        window.addEventListener('focus', syncFromOpener);
        syncFromOpener();
